<script>
const cards=[...document.querySelectorAll('.product')],chips=[...document.querySelectorAll('.chip')],checks=[...document.querySelectorAll('.filter-check')],products=document.getElementById('products');let activeCategory='All',bagCount=0;
function applyFilters(){const search=document.getElementById('mainSearch').value.trim().toLowerCase(),max=+document.getElementById('maxPrice').value;const selected={};checks.forEach(c=>{if(c.checked)(selected[c.dataset.filter]??=[]).push(c.value)});let visible=cards.filter(c=>{return(activeCategory==='All'||c.dataset.category===activeCategory)&&c.dataset.name.includes(search)&&+c.dataset.price<=max&&['category','skin','concern'].every(k=>!selected[k]?.length||selected[k].includes(c.dataset[k]))});const sort=document.getElementById('sort').value;if(sort==='low')visible.sort((a,b)=>+a.dataset.price - +b.dataset.price);if(sort==='high')visible.sort((a,b)=>+b.dataset.price - +a.dataset.price);if(sort==='az')visible.sort((a,b)=>a.dataset.name.localeCompare(b.dataset.name));cards.forEach(c=>c.style.display='none');visible.forEach(c=>{c.style.display='';products.appendChild(c)});document.getElementById('resultCount').textContent=`${visible.length} products`;document.getElementById('empty')?.remove();if(!visible.length){const d=document.createElement('div');d.id='empty';d.className='empty';d.textContent='No products found. Try changing your filters.';products.appendChild(d)}}
chips.forEach(ch=>ch.addEventListener('click',()=>{activeCategory=ch.dataset.category;chips.forEach(c=>c.classList.toggle('active',c===ch));applyFilters()}));checks.forEach(c=>c.addEventListener('change',applyFilters));document.getElementById('sort').addEventListener('change',applyFilters);document.getElementById('mainSearch').addEventListener('input',()=>{document.getElementById('headerSearch').value=document.getElementById('mainSearch').value;applyFilters()});document.getElementById('headerSearch').addEventListener('input',e=>{document.getElementById('mainSearch').value=e.target.value;applyFilters()});document.getElementById('maxPrice').addEventListener('input',e=>{document.getElementById('priceLabel').textContent='₱'+(+e.target.value).toLocaleString();applyFilters()});let toastTimeout;document.querySelectorAll('.add').forEach(b=>b.addEventListener('click',()=>{document.getElementById('bagCount').textContent=++bagCount;const toast=document.getElementById('notice');toast.textContent=b.dataset.product+' added to bag (demo)';toast.style.display='block';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toast.style.display='none',2300)}));applyFilters();
</script>
